//! `match_html_signals` must reproduce what the JS regular expressions
//! stored into existing archives' `technology_signals`.
//! `fixtures/technology-signals-golden.json` was generated by that JS
//! implementation (kept as an oracle in `@nitpicker/archive`'s
//! `src/meta/technologies/structural-signal-definitions.ts`) with
//! `scripts/generate-technology-signals-golden.mjs`: per case, the
//! input as UTF-8 hex (see `nitpicker_html_scan`'s body hash golden for why
//! not a JSON string) and the signals in order, evidence cut to 200 UTF-16
//! code units with a split surrogate pair stored as U+FFFD.

use nitpicker_tech_detect::{SIGNAL_DEFINITIONS, match_html_signals};
use regex::bytes::Regex;
use serde_json::{Value, json};

/// One golden case: its name, input bytes and expected signals.
struct GoldenCase {
	name: String,
	input: Vec<u8>,
	signals: Value,
}

fn golden_cases() -> Vec<GoldenCase> {
	let golden: Value =
		serde_json::from_str(include_str!("fixtures/technology-signals-golden.json"))
			.expect("golden fixture is valid JSON");
	let cases: Vec<GoldenCase> = golden
		.as_array()
		.expect("golden fixture is an array")
		.iter()
		.map(|case| GoldenCase {
			name: case["name"].as_str().expect("case has a name").to_owned(),
			input: decode_hex(case["utf8Hex"].as_str().expect("case has utf8Hex")),
			signals: case["signals"].clone(),
		})
		.collect();
	assert!(!cases.is_empty(), "golden fixture has no cases");
	cases
}

fn decode_hex(hex: &str) -> Vec<u8> {
	assert!(hex.len().is_multiple_of(2), "odd-length hex string");
	(0..hex.len())
		.step_by(2)
		.map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("valid hex digit pair"))
		.collect()
}

#[test]
fn matches_every_golden_case_from_the_js_implementation() {
	for case in golden_cases() {
		let actual: Vec<Value> = match_html_signals(&case.input)
			.into_iter()
			.map(|signal| {
				json!({
					"technology": signal.technology,
					"signalType": signal.signal_type,
					"evidence": signal.evidence,
					"weight": signal.weight,
					"category": signal.category,
				})
			})
			.collect();
		assert_eq!(Value::Array(actual), case.signals, "case: {}", case.name);
	}
}

/// The literal pass skips a pattern on input without its literal, so a
/// literal that is not part of every match would drop signals. Every
/// pattern's full match on every golden input (not the evidence, which may
/// be cut before the literal) must contain it.
#[test]
fn every_match_contains_its_required_literal() {
	let cases = golden_cases();
	for definition in SIGNAL_DEFINITIONS {
		let literal = definition.required_literal;
		let pattern = Regex::new(definition.pattern).expect("valid pattern");
		let mut matched_any = false;
		for case in &cases {
			for found in pattern.find_iter(&case.input) {
				matched_any = true;
				let lowered = found.as_bytes().to_ascii_lowercase();
				assert!(
					lowered
						.windows(literal.len())
						.any(|window| window == literal.as_bytes()),
					"case {}: match of {} lacks {literal}",
					case.name,
					definition.pattern
				);
			}
		}
		assert!(matched_any, "no golden case matches {}", definition.pattern);
	}
}
